async (itx) => {
  const [health] = await Promise.all([
    itx.kit.waveshare.health(),
    itx.agent.append({
      type: "events.iterate.com/agent/summary-updated",
      payload: { activity: "Reading current device health" },
    }),
  ]);
  await Promise.all([
    itx.chat.sendMessage(`The exact current values are: uptimeMs ${health.uptimeMs}, connectionState ${health.connectionState}, and resetReason ${health.resetReason}.`),
    itx.agent.append({
      type: "events.iterate.com/agent/summary-updated",
      payload: { activity: "Reported live health values", waitingFor: "user_input" },
    }),
  ]);
  return;
}

async (itx) => {
  const screenshot = await itx.kit.waveshare.takeScreenshot();
  const chunks = await Promise.all(
    Array.from({ length: screenshot.chunks }, (_, i) => itx.kit.waveshare.readScreenshotChunk(i))
  );
  const totalRead = chunks.reduce((sum, chunk) => {
    if (typeof chunk === "string") return sum + chunk.length;
    if (chunk instanceof Uint8Array) return sum + chunk.byteLength;
    if (chunk instanceof ArrayBuffer) return sum + chunk.byteLength;
    return sum + (chunk as any).byteLength;
  }, 0);
  await Promise.all([
    itx.chat.sendMessage(`The screenshot is ${screenshot.width} by ${screenshot.height}, with ${screenshot.bytes} bytes across ${screenshot.chunks} chunks. I read back ${totalRead} bytes in total.`),
    itx.agent.append({
      type: "events.iterate.com/agent/summary-updated",
      payload: { activity: "Captured and read all screenshot chunks", waitingFor: "user_input" },
    }),
  ]);
  return;
}

