async (itx) => {
  await itx.agent.append({
    type: "events.iterate.com/agent/summary-updated",
    payload: { activity: "Reading device recording status and files" },
  });
  const status = await itx.kit.waveshare.recording.status();
  const size = await itx.kit.waveshare.recording.size("mic.pcm");
  const read = await itx.kit.waveshare.recording.read("call.log", 0);
  const bytes = typeof read === "string"
    ? new TextEncoder().encode(read).byteLength
    : read instanceof Uint8Array
      ? read.byteLength
      : read instanceof ArrayBuffer
        ? read.byteLength
        : (read as any).byteLength;
  await Promise.all([
    itx.chat.sendMessage(`The recording status object is ${JSON.stringify(status)}. The size of mic.pcm is ${size} bytes. Reading call.log from offset zero returned ${bytes} bytes.`),
    itx.agent.append({
      type: "events.iterate.com/agent/summary-updated",
      payload: { activity: "Reported device recording data", waitingFor: "user_input" },
    }),
  ]);
  return;
}

